import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { FiArrowLeft, FiCalendar, FiMapPin, FiUsers, FiImage, FiTrash2, FiShare2, FiDownload } from 'react-icons/fi';
import eventService from '../services/eventService';
import galleryService from '../services/galleryService';
import '../styles/Pages.css';
import { toast } from 'react-toastify';

const PastEventDetailsPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [event, setEvent] = useState(null);
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const [user, setUser] = useState(null);
  const [showUploadForm, setShowUploadForm] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => {
    const userData = JSON.parse(localStorage.getItem('user') || 'null');
    setUser(userData);
    fetchEventDetails();
  }, [id]);

  const fetchEventDetails = async () => {
    setLoading(true);
    try {
      // Fetch event details
      const eventData = await eventService.getEventById(id);
      setEvent(eventData);

      // Fetch gallery images
      const galleryData = await galleryService.getGalleryByEvent(id);
      setImages(galleryData || []);
    } catch (error) {
      console.error('Error fetching event details:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = async (e) => {
    e.preventDefault();
    if (!selectedFile) {
      toast.error('Please select an image file');
      return;
    }

    setUploading(true);
    try {
      const formData = new FormData();
      formData.append('eventId', id);
      formData.append('photo', selectedFile);

      await galleryService.uploadPhoto(id, formData);
      toast.success('Image uploaded successfully!');
      setSelectedFile(null);
      setShowUploadForm(false);
      
      // Refresh gallery
      fetchEventDetails();
    } catch (error) {
      toast.error('Failed to upload image');
      console.error('Upload error:', error);
    } finally {
      setUploading(false);
    }
  };

  const handleDeleteImage = async (photoId) => {
    if (!window.confirm('Are you sure you want to delete this image?')) {
      return;
    }

    try {
      await galleryService.deletePhoto(photoId);
      toast.success('Image deleted successfully!');
      
      // Refresh gallery
      fetchEventDetails();
    } catch (error) {
      toast.error('Failed to delete image');
      console.error('Delete error:', error);
    }
  };

  const handleShareDetails = () => {
    const eventSummary = `
🎉 Event: ${event.title}
📍 Location: ${event.location || 'Not specified'}
📅 Date: ${new Date(event.startDate).toLocaleString()}
📝 Description: ${event.description}
    `.trim();

    // Copy to clipboard
    navigator.clipboard.writeText(eventSummary).then(() => {
      toast.success('Event details copied to clipboard!');
    }).catch(() => {
      toast.error('Failed to copy to clipboard');
    });
  };

  const handleDownloadDetails = () => {
    const eventText = `
Event: ${event.title}
Location: ${event.location || 'Not specified'}
Date: ${new Date(event.startDate).toLocaleString()}
Type: ${event.eventType === 'indoor' ? 'Indoor' : 'Outdoor'}
Total Seats: ${event.totalSeats || 'N/A'}
Description: ${event.description}
    `.trim();

    const element = document.createElement('a');
    element.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(eventText));
    element.setAttribute('download', `${event.title}-details.txt`);
    element.style.display = 'none';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
    toast.success('Event details downloaded!');
  };

  if (loading) {
    return <div className="loading">Loading event details...</div>;
  }

  if (!event) {
    return (
      <div className="error-container">
        <h2>Event Not Found</h2>
        <button className="btn-primary" onClick={() => navigate('/past-events')}>
          Back to Past Events
        </button>
      </div>
    );
  }

  return (
    <div className="past-event-details-page">
      {/* Back Button */}
      <button 
        className="back-btn"
        onClick={() => navigate('/past-events')}
      >
        <FiArrowLeft size={20} /> Back to Past Events
      </button>

      {/* Event Header */}
      <div className="event-header">
        <div className="event-header-content">
          <h1>{event.title}</h1>
          <span className="event-status-badge completed">🎉 Completed</span>
        </div>
        <p className="event-description">{event.description}</p>
      </div>

      {/* Event Details Grid */}
      <div className="event-info-grid">
        <div className="info-card">
          <div className="info-icon">
            <FiCalendar size={24} />
          </div>
          <div className="info-content">
            <h3>Event Date</h3>
            <p>{new Date(event.startDate).toLocaleDateString()}</p>
            <small>{new Date(event.startDate).toLocaleTimeString()}</small>
          </div>
        </div>

        <div className="info-card">
          <div className="info-icon">
            <FiMapPin size={24} />
          </div>
          <div className="info-content">
            <h3>Location</h3>
            <p>{event.location || 'Not specified'}</p>
          </div>
        </div>

        <div className="info-card">
          <div className="info-icon">
            <FiUsers size={24} />
          </div>
          <div className="info-content">
            <h3>Event Type</h3>
            <p>{event.eventType === 'indoor' ? '🏢 Indoor' : '🌳 Outdoor'}</p>
            {event.eventType === 'indoor' && <small>Total Seats: {event.totalSeats}</small>}
          </div>
        </div>

        <div className="info-card">
          <div className="info-icon">
            <FiImage size={24} />
          </div>
          <div className="info-content">
            <h3>Photo Memories</h3>
            <p>{images.length} photos</p>
          </div>
        </div>
      </div>

      {/* Gallery Section */}
      <div className="gallery-section">
        <div className="gallery-header">
          <div>
            <h2>📸 Event Gallery</h2>
            <p>Memories from {event.title}</p>
          </div>
          <div className="gallery-actions">
            <button 
              className="btn-primary"
              onClick={handleShareDetails}
            >
              <FiShare2 size={18} /> Share Details
            </button>
            <button 
              className="btn-secondary"
              onClick={handleDownloadDetails}
            >
              <FiDownload size={18} /> Download
            </button>
            {(user?.role === 'admin' || user?.role === 'organizer') && (
              <button 
                className="btn-success"
                onClick={() => setShowUploadForm(!showUploadForm)}
              >
                <FiImage size={18} /> {showUploadForm ? 'Cancel Upload' : 'Upload Photo'}
              </button>
            )}
          </div>
        </div>

        {/* Upload Form */}
        {showUploadForm && (user?.role === 'admin' || user?.role === 'organizer') && (
          <div className="upload-form-section">
            <form onSubmit={handleImageUpload} className="image-upload-form">
              <div className="form-group">
                <label htmlFor="photo">Select Image *</label>
                <input
                  type="file"
                  id="photo"
                  accept="image/*"
                  onChange={(e) => setSelectedFile(e.target.files[0])}
                  required
                  className="file-input"
                />
              </div>
              <button 
                type="submit" 
                className="btn-success"
                disabled={uploading}
              >
                {uploading ? 'Uploading...' : 'Upload Image'}
              </button>
            </form>
          </div>
        )}

        {images.length > 0 ? (
          <>
            {/* Main Image Display */}
            {selectedImage && (
              <div className="main-image-container">
                <div className="main-image-wrapper">
                  <img 
                    src={selectedImage} 
                    alt="Selected event" 
                    className="main-image"
                  />
                  <button 
                    className="close-main-image"
                    onClick={() => setSelectedImage(null)}
                  >
                    ✕
                  </button>
                </div>
              </div>
            )}

            {/* Gallery Grid */}
            <div className="gallery-grid">
              {images.map((image, index) => (
                <div 
                  key={index} 
                  className="gallery-item"
                  onClick={() => setSelectedImage(image)}
                >
                  <img 
                    src={image} 
                    alt={`Event ${index + 1}`}
                    className="gallery-thumbnail"
                  />
                  <div className="gallery-overlay">
                    <span>View</span>
                  </div>
                </div>
              ))}
            </div>
          </>
        ) : (
          <div className="no-gallery">
            <p>📷 No photos uploaded for this event yet</p>
          </div>
        )}
      </div>

      {/* Event Details Summary */}
      <div className="event-summary">
        <h3>Event Summary</h3>
        <div className="summary-content">
          <p>
            <strong>Title:</strong> {event.title}
          </p>
          <p>
            <strong>Duration:</strong> {new Date(event.startDate).toLocaleString()} - {new Date(event.endDate).toLocaleString()}
          </p>
          <p>
            <strong>Location:</strong> {event.location || 'Not specified'}
          </p>
          <p>
            <strong>Type:</strong> {event.eventType === 'indoor' ? 'Indoor' : 'Outdoor'}
          </p>
          {event.eventType === 'indoor' && (
            <p>
              <strong>Total Seats:</strong> {event.totalSeats}
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default PastEventDetailsPage;
